SELECT SUM( a.money ) as moneyhj, SUM( a.profit_money ) as profit_money_hj, d.dept_name as department FROM sys_project_value a INNER JOIN sys_project b ON a.project_id = b.project_id INNER JOIN sys_user c ON a.user_name = c.user_name INNER JOIN sys_dept d ON c.dept_id = d.dept_id
and b.user_name_alias = #{userNameAlias}
and b.department = #{department}
and YEAR(b.settle_time) = YEAR(NOW())
GROUP BY d.dept_name;

